const esc = (value = '') => String(value).replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const pretty = (value = 'draft') => String(value).replace(/_/g, ' ');
const typeName = type => ({ guide_article: 'Blog post', carousel: 'Carousel', reel: 'Instagram Reel', image_post: 'Image post', pin: 'Pinterest Pin', x_post: 'X post', tiktok: 'TikTok', reddit_reply: 'Reddit reply' }[type] || pretty(type));
