async function call(action, body = {}) {
  const { data, error } = await supabase.functions.invoke('marketing-admin', { body: { action, ...body } });
  if (!error && !data?.reason) return data;
  let reason = data?.reason;
  if (!reason && error?.context?.json) { try { reason = (await error.context.json())?.reason; } catch {} }
  if (reason === 'forbidden' || error?.context?.status === 403) throw new Error('This account is not authorized for the Grovio marketing workspace.');
  if (reason === 'ai_not_configured') throw new Error('OpenAI is not connected yet. Add OPENAI_API_KEY as a Supabase Edge Function secret, then try again.');
  if (reason === 'approved_source_required') throw new Error('Choose an approved Grovio source asset before generating a creative.');
  if (reason === 'ai_generation_failed') throw new Error('OpenAI could not generate this creative right now. No draft was saved; please try again.');
  if (reason === 'ai_video_failed') throw new Error('OpenAI could not prepare this video right now. The editable storyboard is still saved.');
  throw new Error(reason || 'The marketing workspace could not complete that request.');
}

async function optional(action, key) { try { return await call(action); } catch { return { [key]: [] }; } }
async function load() {
  state.loading = true; render();
  try {
    const [dashboard, campaigns, content, assets, connections, communities, opportunities, profile] = await Promise.all([
      call('dashboard'), call('list_campaigns'), call('list_content'), call('list_assets'), call('list_connections'),
      optional('list_reddit_communities', 'communities'), optional('list_reddit_opportunities', 'opportunities'),
      optional('get_brand_profile', 'brand_profile'),
    ]);
    Object.assign(state, { dashboard, campaigns: campaigns.campaigns || [], content: content.content || [], assets: assets.assets || [], connections: connections.connections || [], communities: communities.communities || [], opportunities: opportunities.opportunities || [], error: '' });
    if (profile?.brand_profile && !Array.isArray(profile.brand_profile)) state.brand = { ...state.brand, ...profile.brand_profile };
  } catch (error) { state.error = error.message || 'The workspace is not connected yet.'; }
  state.loading = false; render();
}

