function calendarDate(value) { const current = new Date(value); return `${current.getFullYear()}-${String(current.getMonth() + 1).padStart(2, '0')}-${String(current.getDate()).padStart(2, '0')}`; }
function localDateTimeValue(value) { if (!value) return ''; const current = new Date(value); const adjusted = new Date(current.getTime() - current.getTimezoneOffset() * 60000); return adjusted.toISOString().slice(0, 16); }
function mondayFor(offset = state.calendarOffset || 0) { const current = new Date(); current.setHours(0, 0, 0, 0); current.setDate(current.getDate() - ((current.getDay() + 6) % 7) + offset * 7); return current; }
function calendarDays() { const monday = mondayFor(); return Array.from({ length: 7 }, (_, index) => { const current = new Date(monday); current.setDate(monday.getDate() + index); return current; }); }
function scheduleModal(contentId = '') { const choices = state.content.filter(item => !['published', 'archived'].includes(item.status)).map(item => `<option value="${esc(item.id)}" ${item.id === contentId ? 'selected' : ''}>${esc(typeName(item.content_type))} — ${esc(item.title)}</option>`).join(''); const selected = state.content.find(item => item.id === contentId); modal('Schedule a post', 'The calendar only shows content with an explicit date and time. Saving this does not publish it anywhere.', `<form class="form" data-form="schedule"><label>Draft to schedule<select required name="id"><option value="">Choose a draft</option>${choices}</select></label><label>Scheduled date and time<input required type="datetime-local" name="scheduled_for" value="${localDateTimeValue(selected?.scheduled_for)}"></label><p class="form-note">You can keep editing this draft after it is scheduled. Publishing remains a separate, manual step.</p><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn">Save schedule</button></div></form>`); }
