  const calendar = days.map((day, index) => { const key = calendarDate(day); const posts = scheduled.filter(item => calendarDate(item.scheduled_for) === key); return `<div class="calendar-day"><b>${['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][index]} <small>${day.getDate()}</small></b>${posts.length ? posts.map(item => `<button data-content="${esc(item.id)}"><span>${esc(new Intl.DateTimeFormat('en', { hour: 'numeric', minute: '2-digit' }).format(new Date(item.scheduled_for)))}</span><strong>${esc(typeName(item.content_type))}</strong>${esc(item.title)}</button>`).join('') : `<button class="add-slot" data-create="calendar">+ Schedule post</button>`}</div>`; }).join('');
