function slidesFor(title, message) { return [title, message, 'Make the next step smaller.', 'Keep the actual proof close.', 'See a calmer way to hold it together.']; }
function scenesFor(title, message) { return [`Hook: ${title}`, 'Show: a real Grovio screen that supports the point.', `Say: ${message}`, 'Close: one useful, honest next step.']; }
function imageFrom(url) { return new Promise(resolve => { if (!url) return resolve(null); const image = new Image(); image.crossOrigin = 'anonymous'; image.onload = () => resolve(image); image.onerror = () => resolve(null); image.src = url; }); }
function wrapText(context, value, width, limit = 7) { const words = String(value).split(/\s+/); const lines = []; let line = ''; for (const word of words) { const next = line ? `${line} ${word}` : word; if (context.measureText(next).width > width && line) { lines.push(line); line = word; if (lines.length === limit) break; } else line = next; } if (line && lines.length < limit) lines.push(line); return lines; }
async function renderCarouselSlide(slide, index, total, sourceUrl) {
  const canvas = document.createElement('canvas'); canvas.width = 1080; canvas.height = 1080; const context = canvas.getContext('2d');
  const colors = [['#F7F4EE', '#2C2218'], ['#E5EFE4', '#29472F'], ['#F1E8D9', '#6E4729'], ['#E8EEF0', '#315564'], ['#4A6E4E', '#FFFFFF']]; const [background, ink] = colors[index % colors.length]; context.fillStyle = background; context.fillRect(0, 0, 1080, 1080);
  context.fillStyle = index === total - 1 ? '#FFFFFF' : '#4A6E4E'; context.font = '700 34px Plus Jakarta Sans, sans-serif'; context.fillText('grovio', 76, 100); context.textAlign = 'right'; context.font = '700 24px Plus Jakarta Sans, sans-serif'; context.fillText(`${index + 1} / ${total}`, 1004, 100); context.textAlign = 'left';
  const source = await imageFrom(sourceUrl); if (source && index > 0) { context.save(); context.fillStyle = '#FFFFFF'; context.roundRect(650, 240, 320, 560, 30); context.fill(); context.beginPath(); context.roundRect(675, 265, 270, 510, 20); context.clip(); const ratio = Math.max(270 / source.width, 510 / source.height); const width = source.width * ratio; const height = source.height * ratio; context.drawImage(source, 810 - width / 2, 520 - height / 2, width, height); context.restore(); }
  context.fillStyle = ink; context.font = `800 ${index === 0 ? 86 : 64}px Nunito, sans-serif`; const lineWidth = source && index > 0 ? 500 : 875; const lines = wrapText(context, slide, lineWidth, 7); const top = index === 0 ? 365 : 340; lines.forEach((line, lineIndex) => context.fillText(line, 78, top + lineIndex * (index === 0 ? 96 : 75))); context.fillStyle = index === total - 1 ? '#E5EFE4' : '#4A6E4E'; context.font = '600 27px Plus Jakarta Sans, sans-serif'; context.fillText(index === total - 1 ? 'Keep the proof close, without making it the point.' : 'A calmer homeschool rhythm', 78, 965);
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png')); if (!blob) throw new Error('Could not render the carousel slide.'); return { blob, previewUrl: canvas.toDataURL('image/png') };
}
async function saveGeneratedSlide(blob, label, alt) { const file = new File([blob], `${label.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'grovio-carousel'}.png`, { type: 'image/png' }); const upload = await call('create_asset_upload', { file_name: file.name, content_type: file.type, byte_size: file.size }); const { error } = await supabase.storage.from('marketing-assets').uploadToSignedUrl(upload.upload.path, upload.upload.token, file, { contentType: file.type, cacheControl: '3600' }); if (error) throw error; const result = await call('create_asset', { label, kind: 'image', storage_path: upload.upload.path, alt_text: alt, approved: true }); return result.asset; }
async function createCarouselSlides(title, slides, featuredAssetId) { const source = asset(featuredAssetId); const result = []; for (const [index, slide] of slides.entries()) { const rendered = await renderCarouselSlide(slide, index, slides.length, source?.preview_url); const label = `${title} — slide ${index + 1}`; if (state.preview) { const item = { id: id(), label, kind: 'image', approved: true, alt_text: `Carousel slide ${index + 1}: ${slide}`, preview_url: rendered.previewUrl }; state.assets.unshift(item); result.push(item); } else result.push(await saveGeneratedSlide(rendered.blob, label, `Carousel slide ${index + 1}: ${slide}`)); } return result; }
function draftsFor(kind, title, message, keyword, target) { const now = new Date().toISOString(); const make = (content_type, label, caption) => ({ id: id(), content_type, title: label, caption: `${caption}${target ? `\n\n${target}` : ''}`, primary_keyword: keyword || title, target_url: target, status: 'draft', updated_at: now }); if (kind === 'pin') return [make('pin', `A calmer way to handle ${title}`, message), make('pin', `3 small shifts for ${title}`, 'A practical, useful checklist parents can save.'), make('pin', `What helps when ${title} feels heavy`, 'A gentle reminder and a clear next step.')]; if (kind === 'x') return [make('x_post', 'A small thought for today', `You do not need a perfect system for ${title}. You need one small rhythm you can keep on an ordinary Tuesday.`), make('x_post', 'A practical reminder', `If ${title} feels overwhelming, make the next step smaller—not the standard higher.`), make('x_post', 'A question worth sitting with', `What would make ${title} feel more supportive this week?`)]; return []; }
function previewOpenAICreative(format, values) { const hook = values.title; const message = values.message; return { creative: { title: hook, hook, headline: hook, caption: `${message}\n\nA calm next step is enough for today.`, voiceover: `You do not need a perfect system. ${message}`, visual_direction: 'A warm, candid homeschool moment with soft cream and sage tones, leaving room for the real Grovio screen.', slides: format === 'carousel' ? [hook, 'The learning you are already doing counts.', message, 'Keep the actual proof close.', 'A calmer way to hold it together.'] : [], scenes: format === 'reel' ? [`Hook: ${hook}`, 'Show the selected real Grovio screen.', `Say: ${message}`, 'Close with one useful next step.'] : [] }, generated_asset: null }; }
async function generateOpenAICreative(format, values) { if (state.preview) return previewOpenAICreative(format, values); return call('generate_openai_creative', { format, title: values.title, message: values.message, primary_keyword: values.primary_keyword, target_url: values.target_url, featured_asset_id: values.featured_asset_id || null }); }
async function saveCreation(form) {
  const kind = form.dataset.creation; const values = Object.fromEntries(new FormData(form).entries()); const now = new Date().toISOString(); const close = () => document.querySelector('.dialog')?.remove();
  try {
    if (kind === 'article') { const record = { id: id(), ...values, content_type: 'guide_article', status: 'draft', updated_at: now }; if (state.preview) state.content.unshift(record); else await call('create_content', record); state.view = 'seo'; state.error = state.preview ? 'SEO draft saved in this local preview only.' : ''; close(); return state.preview ? render() : load(); }
    if (['pin', 'x'].includes(kind)) { const records = draftsFor(kind, values.title, values.message, values.primary_keyword, values.target_url); if (state.preview) state.content.unshift(...records); else await Promise.all(records.map(record => call('create_content', { ...record, id: undefined }))); state.view = 'studio'; state.error = state.preview ? 'Draft queue generated in this local preview only.' : ''; close(); return state.preview ? render() : load(); }
    const contentType = ['reel', 'image-to-reel'].includes(kind) ? 'reel' : kind === 'carousel' ? 'carousel' : 'image_post'; const usingOpenAI = values.use_openai === 'on'; const submit = form.querySelector('.form-actions .btn:not(.secondary)'); if (usingOpenAI && submit) { submit.disabled = true; submit.textContent = 'Creating with ChatGPT…'; }
    const ai = usingOpenAI ? await generateOpenAICreative(contentType, values) : null; const creative = ai?.creative || {}; const plannedTitle = creative.title || values.title; const plannedCaption = creative.caption || values.message; const slides = contentType === 'carousel' ? (creative.slides?.length === 5 ? creative.slides : slidesFor(plannedTitle, plannedCaption)) : null; const slideAssets = slides ? await createCarouselSlides(plannedTitle, slides, values.featured_asset_id) : []; const plannedScenes = contentType === 'reel' ? (creative.scenes?.length === 4 ? creative.scenes : scenesFor(plannedTitle, plannedCaption)) : []; const aiBrief = usingOpenAI ? { hook: creative.hook || plannedTitle, headline: creative.headline || plannedTitle, voiceover: creative.voiceover || null, visual_direction: creative.visual_direction || null, supporting_asset_id: ai?.generated_asset?.id || null } : null; const structured_data = slides ? { slides, slide_asset_ids: slideAssets.map(item => item.id), source_asset_id: values.featured_asset_id || null, ai_brief: aiBrief } : contentType === 'reel' ? { scenes: plannedScenes, generated_video_asset_id: null, openai_video: ai?.video_job || null, source_asset_id: values.featured_asset_id || null, ai_brief: aiBrief } : { headline: creative.headline || plannedTitle, source_asset_id: values.featured_asset_id || null, ai_brief: aiBrief }; const record = { id: id(), content_type: contentType, title: `${contentType === 'reel' ? 'Reel: ' : ''}${plannedTitle}`, caption: plannedCaption, primary_keyword: values.primary_keyword, target_url: values.target_url, featured_asset_id: values.featured_asset_id || null, structured_data, status: 'draft', updated_at: now };
    if (state.preview) state.content.unshift(record); else await call('create_content', { ...record, id: undefined }); state.view = 'studio'; state.error = state.preview ? (usingOpenAI ? 'Local preview created a non-publishing storyboard only; a real AI video is requested only in the deployed workspace after the key is configured.' : `${typeName(contentType)} plan saved in this local preview only.`) : usingOpenAI ? (contentType === 'reel' ? 'The editable storyboard is saved and an AI video is being prepared for review. It will never publish automatically.' : 'ChatGPT creative and a review-only supporting image were added. The selected Grovio screen remains the real source in the final draft.') : ''; close(); return state.preview ? render() : load();
  } catch (error) { state.error = error.message || 'Could not save this draft.'; close(); render(); }
}
async function uploadAssetFile(file) { const upload = await call('create_asset_upload', { file_name: file.name, content_type: file.type, byte_size: file.size }); const { error } = await supabase.storage.from('marketing-assets').uploadToSignedUrl(upload.upload.path, upload.upload.token, file, { contentType: file.type, cacheControl: '3600' }); if (error) throw error; return upload.upload.path; }
async function saveAsset(form) { const data = new FormData(form); const values = Object.fromEntries([...data.entries()].filter(([key]) => key !== 'file')); try { const file = data.get('file'); const storagePath = file instanceof File && file.size ? await uploadAssetFile(file) : null; if (state.preview) { state.assets.unshift({ id: id(), ...values, approved: data.get('approved') === 'on', preview_url: file instanceof File && file.size ? URL.createObjectURL(file) : values.source_url }); state.error = 'Asset saved in this local preview only.'; } else { if (!storagePath && !values.source_url) throw new Error('Choose a private source file or enter an existing asset URL.'); await call('create_asset', { ...values, storage_path: storagePath, approved: data.get('approved') === 'on' }); } state.view = 'library'; document.querySelector('.dialog')?.remove(); state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not save this asset.'; document.querySelector('.dialog')?.remove(); render(); } }
async function saveAssetEdit(form) { const item = asset(form.dataset.id); if (!item) return; const data = new FormData(form); const values = Object.fromEntries([...data.entries()].filter(([key]) => key !== 'file')); try { const file = data.get('file'); const storagePath = file instanceof File && file.size ? await uploadAssetFile(file) : null; const next = { ...values, approved: data.get('approved') === 'on', ...(storagePath ? { storage_path: storagePath } : {}) }; if (state.preview) Object.assign(item, next, { preview_url: storagePath ? URL.createObjectURL(file) : (values.source_url || item.preview_url) }); else await call('update_asset', { id: item.id, ...next }); state.view = 'library'; document.querySelector('.dialog')?.remove(); state.error = state.preview ? 'Asset changes are saved in this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not update this asset.'; document.querySelector('.dialog')?.remove(); render(); } }
async function deleteAsset(assetId) { const item = asset(assetId); if (!item || !window.confirm(`Delete “${item.label}” from the private asset library?`)) return; try { if (state.preview) state.assets = state.assets.filter(row => row.id !== assetId); else await call('delete_asset', { id: assetId }); document.querySelector('.dialog')?.remove(); state.view = 'library'; state.error = state.preview ? 'Asset removed from this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not delete this asset.'; render(); } }
async function saveGeneric(form) { const type = form.dataset.form; const values = Object.fromEntries(new FormData(form).entries()); if (type === 'brand') { const brand = { ...values, colors: String(values.colors || '').split(',').map(color => color.trim()).filter(Boolean) }; try { if (state.preview) Object.assign(state.brand, brand); else { const response = await call('upsert_brand_profile', brand); state.brand = { ...state.brand, ...(response.brand_profile || brand) }; } state.error = state.preview ? 'Brand DNA saved in this local preview only.' : ''; document.querySelector('.dialog')?.remove(); return render(); } catch (error) { state.error = error.message || 'Could not save Brand DNA.'; document.querySelector('.dialog')?.remove(); return render(); } } try { if (state.preview) { if (type === 'community') state.communities.unshift({ id: id(), ...values }); if (type === 'opportunity') state.opportunities.unshift({ id: id(), ...values, relevance_score: Number(values.relevance_score), status: 'new', community: state.communities.find(item => item.id === values.community_id) }); state.error = 'Saved in this local preview only.'; } else if (type === 'community') await call('create_reddit_community', values); else if (type === 'opportunity') await call('create_reddit_opportunity', values); state.view = 'reddit'; document.querySelector('.dialog')?.remove(); state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not save that item.'; document.querySelector('.dialog')?.remove(); render(); } }

function reviewMedia(item, label = '') { if (!item?.preview_url) return ''; return `<div class="review-media">${label ? `<small>${esc(label)}</small>` : ''}${item.kind === 'video' ? `<video src="${esc(item.preview_url)}" controls playsinline></video>` : `<img src="${esc(item.preview_url)}" alt="${esc(item.alt_text || item.label)}">`}</div>`; }
function openAsset(assetId) { const item = asset(assetId); if (!item) return; modal(item.label, `${pretty(item.kind)} · ${item.approved ? 'approved for content' : 'needs review'}`, `<div class="detail">${reviewMedia(item)}<p>${esc(item.alt_text || 'No product description is saved for this asset yet.')}</p><p><b>Creative status:</b> ${item.approved ? 'Eligible for use in carousels, Reels, Pins, and other drafts.' : 'Keep this out of new content until it is approved.'}</p><div class="detail-actions"><button class="btn secondary" data-close>Close</button><button class="btn secondary" data-edit-asset="${esc(item.id)}">Edit asset</button><button class="btn" data-create="reel">Create a Reel from this kind of asset</button></div></div>`); }
function contentAssetOptions(selectedId) { return `<option value="">No source asset selected</option>${state.assets.map(item => `<option value="${esc(item.id)}" ${item.id === selectedId ? 'selected' : ''}>${esc(item.label)}${item.approved ? ' — approved' : ''}</option>`).join('')}`; }
function contentStatusOptions(status) { return ['idea', 'draft', 'in_review', 'approved', 'scheduled', 'archived'].map(value => `<option value="${value}" ${status === value ? 'selected' : ''}>${esc(pretty(value))}</option>`).join(''); }
function contentEditor(item) { const data = item.structured_data || {}; const sourceId = data.source_asset_id || item.featured_asset_id || ''; const socialCopy = item.caption || ''; const article = item.content_type === 'guide_article'; const slides = item.content_type === 'carousel' ? Array.from({ length: 5 }, (_, index) => data.slides?.[index] || '') : []; const scenes = item.content_type === 'reel' ? (data.scenes || []).join('\n') : ''; const visualControls = item.content_type === 'carousel' ? `<label class="check editor-check"><input type="checkbox" name="rerender"> Create a new editable slide set from these changes</label><p class="form-note">The current slide files remain in the private library for reference until you remove them.</p>` : item.content_type === 'reel' ? `<label class="check editor-check"><input type="checkbox" name="rerender"> Request a fresh 4-second AI video from this storyboard</label><p class="form-note">The video is a review draft. It will never be published automatically or used to recreate the Grovio interface.</p>` : ''; return `<form class="form editor-form" data-form="content" data-id="${esc(item.id)}"><div class="form-grid"><label>Working title<input required name="title" value="${esc(item.title)}"></label><label>Status<select name="status">${contentStatusOptions(item.status)}</select></label></div><div class="form-grid"><label>Scheduled date and time<input type="datetime-local" name="scheduled_for" value="${localDateTimeValue(item.scheduled_for)}"></label><label>Source asset<select name="featured_asset_id">${contentAssetOptions(sourceId)}</select></label></div><label>Primary keyword<input name="primary_keyword" value="${esc(item.primary_keyword || '')}"></label>${article ? `<label>Reader-facing excerpt<textarea name="excerpt">${esc(item.excerpt || '')}</textarea></label><label>SEO title<input name="seo_title" value="${esc(item.seo_title || '')}"></label><label>Meta description<textarea name="meta_description">${esc(item.meta_description || '')}</textarea></label><label>Search intent<input name="search_intent" value="${esc(item.search_intent || '')}"></label><label>Article draft<textarea name="body_markdown" class="editor-body">${esc(item.body_markdown || '')}</textarea></label>` : `<label>Caption / post copy<textarea name="caption">${esc(socialCopy)}</textarea></label><label>Destination URL<input type="url" name="target_url" value="${esc(item.target_url || '')}" placeholder="https://grovioapp.com/guide/..."></label>`}${item.content_type === 'carousel' ? `<fieldset><legend>Carousel slide copy</legend>${slides.map((slide, index) => `<label>Slide ${index + 1}<textarea required name="slide_${index + 1}">${esc(slide)}</textarea></label>`).join('')}</fieldset>` : ''}${item.content_type === 'reel' ? `<label>Storyboard — one scene per line<textarea required name="scenes">${esc(scenes)}</textarea></label><label>Voiceover (optional)<textarea name="voiceover">${esc(data.ai_brief?.voiceover || '')}</textarea></label>` : ''}${visualControls}<p class="form-note">Scheduling records an intended date and time only. This workspace cannot publish the post.</p><div class="form-actions"><button type="button" class="btn danger" data-delete-content="${esc(item.id)}">Delete draft</button><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn">Save changes</button></div></form>`; }
function openContent(contentId) { const item = state.content.find(row => row.id === contentId); if (!item) return; const data = item.structured_data || {}; const source = asset(data.source_asset_id || item.featured_asset_id); const slideAssets = (data.slide_asset_ids || []).map(asset).filter(Boolean); const reelAsset = asset(data.generated_video_asset_id); const aiAsset = asset(data.ai_brief?.supporting_asset_id); const videoJob = data.openai_video; const slides = data.slides ? `<div class="slide-stack">${data.slides.map((slide, index) => `<div><small>Slide ${index + 1}</small><b>${esc(slide)}</b></div>`).join('')}</div>${slideAssets.length ? `<div class="review-asset-grid">${slideAssets.map((slide, index) => `<button data-asset="${esc(slide.id)}">${reviewMedia(slide, `Rendered slide ${index + 1}`)}</button>`).join('')}</div>` : ''}` : ''; const scenes = data.scenes ? `<ol class="scene-list">${data.scenes.map(scene => `<li>${esc(scene)}</li>`).join('')}</ol>` : ''; const videoNote = videoJob ? `<div class="ai-notes"><b>AI video draft</b><p>Status: ${esc(pretty(videoJob.status || 'queued'))}. It is a supporting clip for review, never an automatic social post.</p>${reelAsset ? '' : `<button class="btn secondary" data-refresh-video="${esc(item.id)}">Check video status</button>`}</div>` : item.content_type === 'reel' && !reelAsset ? `<div class="ai-notes"><b>No video attached yet</b><p>This is an editable Reel storyboard. Request a real AI review video from the controls below when you are ready.</p></div>` : ''; const aiNotes = data.ai_brief ? `<div class="ai-notes"><b>ChatGPT creative direction</b><p>${esc(data.ai_brief.hook || data.ai_brief.headline || '')}</p>${data.ai_brief.voiceover ? `<p><b>Voiceover:</b> ${esc(data.ai_brief.voiceover)}</p>` : ''}${aiAsset ? `<button class="text-button" data-asset="${esc(aiAsset.id)}">Open the supporting visual (needs review) →</button>` : ''}</div>` : ''; modal(item.title, `${typeName(item.content_type)} · ${pretty(item.status)}`, `<div class="detail"><div class="detail-meta"><span class="type-pill">${esc(typeName(item.content_type))}</span><span class="status ${esc(item.status)}">${esc(pretty(item.status))}</span></div>${source ? `<p><b>Real Grovio source:</b> ${esc(source.label)}</p>` : ''}${reelAsset ? reviewMedia(reelAsset, 'AI Reel review video') : ''}${videoNote}${slides}${scenes}${aiNotes}</div>${contentEditor(item)}`); }
function contentUpdatePayload(item, changes) { return { id: item.id, content_type: item.content_type, title: item.title, slug: item.slug, excerpt: item.excerpt, body_markdown: item.body_markdown, primary_keyword: item.primary_keyword, supporting_keywords: item.supporting_keywords || [], search_intent: item.search_intent, seo_title: item.seo_title, meta_description: item.meta_description, canonical_url: item.canonical_url, target_url: item.target_url, featured_asset_id: item.featured_asset_id, structured_data: item.structured_data || {}, status: item.status, scheduled_for: item.scheduled_for, ...changes }; }
async function saveContentEdit(form) { const item = state.content.find(row => row.id === form.dataset.id); if (!item) return; const values = Object.fromEntries(new FormData(form).entries()); try { const structured = JSON.parse(JSON.stringify(item.structured_data || {})); const selectedAsset = values.featured_asset_id || null; structured.source_asset_id = selectedAsset; if (item.content_type === 'carousel') { structured.slides = Array.from({ length: 5 }, (_, index) => String(values[`slide_${index + 1}`] || '').trim()); if (structured.slides.some(value => !value)) throw new Error('Give each carousel slide copy before saving.'); if (values.rerender === 'on') structured.slide_asset_ids = (await createCarouselSlides(values.title, structured.slides, selectedAsset)).map(row => row.id); } if (item.content_type === 'reel') { structured.scenes = String(values.scenes || '').split('\n').map(scene => scene.trim()).filter(Boolean).slice(0, 6); if (!structured.scenes.length) throw new Error('Add at least one Reel scene before saving.'); structured.ai_brief = { ...(structured.ai_brief || {}), voiceover: String(values.voiceover || '').trim() || null }; if (values.rerender === 'on') { if (state.preview) throw new Error('AI video generation is available only after the deployed workspace has an OpenAI key.'); const ai = await generateOpenAICreative('reel', { title: values.title, message: values.caption || item.caption || values.title, primary_keyword: values.primary_keyword, target_url: values.target_url, featured_asset_id: selectedAsset }); structured.openai_video = ai?.video_job || null; structured.generated_video_asset_id = null; } } const scheduledFor = values.scheduled_for ? new Date(values.scheduled_for).toISOString() : null; if (values.status === 'scheduled' && !scheduledFor) throw new Error('Choose a date and time before scheduling this post.'); const next = contentUpdatePayload(item, { title: values.title, status: values.status, scheduled_for: scheduledFor, featured_asset_id: selectedAsset, primary_keyword: values.primary_keyword, target_url: values.target_url, excerpt: values.excerpt, body_markdown: values.body_markdown, seo_title: values.seo_title, meta_description: values.meta_description, search_intent: values.search_intent, caption: values.caption, structured_data: structured, updated_at: new Date().toISOString() }); if (state.preview) Object.assign(item, next); else await call('update_content', next); document.querySelector('.dialog')?.remove(); state.error = state.preview ? 'Draft changes are saved in this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not save this draft.'; document.querySelector('.dialog')?.remove(); render(); } }
async function refreshGeneratedVideo(contentId) { if (state.preview) { state.error = 'The local preview does not request or download AI videos.'; document.querySelector('.dialog')?.remove(); return render(); } try { const response = await call('resolve_openai_video', { content_id: contentId }); document.querySelector('.dialog')?.remove(); state.error = response.video_job?.status === 'completed' ? 'AI Reel video added to the private review library.' : `AI Reel video is ${pretty(response.video_job?.status || 'queued')}. Check back in a moment.`; await load(); } catch (error) { state.error = error.message || 'Could not check this AI video.'; document.querySelector('.dialog')?.remove(); render(); } }
async function saveSchedule(form) { const values = Object.fromEntries(new FormData(form).entries()); const item = state.content.find(row => row.id === values.id); if (!item) return; try { const scheduledFor = new Date(values.scheduled_for).toISOString(); if (Number.isNaN(new Date(scheduledFor).getTime())) throw new Error('Choose a valid date and time.'); const next = contentUpdatePayload(item, { status: 'scheduled', scheduled_for: scheduledFor, updated_at: new Date().toISOString() }); if (state.preview) Object.assign(item, next); else await call('update_content', next); document.querySelector('.dialog')?.remove(); state.error = state.preview ? 'Scheduled in this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not schedule this draft.'; document.querySelector('.dialog')?.remove(); render(); } }
async function deleteContent(contentId) { const item = state.content.find(row => row.id === contentId); if (!item || !window.confirm(`Delete “${item.title}”? This cannot publish or restore it.`)) return; try { if (state.preview) state.content = state.content.filter(row => row.id !== contentId); else await call('delete_content', { id: contentId }); document.querySelector('.dialog')?.remove(); state.error = state.preview ? 'Draft removed from this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not delete this draft.'; render(); } }
function openOpportunity(opportunityId) { const item = state.opportunities.find(row => row.id === opportunityId); if (!item) return; modal(item.source_title, `${item.community?.name || 'Community'} · ${item.relevance_score || '—'}% relevance`, `<form class="form" data-form="reply" data-id="${esc(item.id)}"><p><a class="btn secondary" href="${esc(item.source_url)}" target="_blank" rel="noreferrer">Open original conversation</a></p><label>Context<textarea readonly>${esc(item.source_excerpt || 'No saved context.')}</textarea></label><label>Human-reviewed reply draft<textarea name="draft_reply">${esc(item.draft_reply || '')}</textarea></label><label>Queue status<select name="status"><option value="new">New</option><option value="watching">Watching</option><option value="drafted" ${item.status === 'drafted' ? 'selected' : ''}>Drafted</option><option value="approved">Approved</option><option value="replied">Replied manually</option><option value="dismissed">Dismissed</option></select></label><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn">Save reply draft</button></div></form>`); }
async function saveReply(form) { const item = state.opportunities.find(row => row.id === form.dataset.id); const values = Object.fromEntries(new FormData(form).entries()); try { if (state.preview && item) Object.assign(item, values); else await call('update_reddit_opportunity', { id: form.dataset.id, ...values }); document.querySelector('.dialog')?.remove(); state.error = state.preview ? 'Reply draft saved in this local preview only.' : ''; state.preview ? render() : await load(); } catch (error) { state.error = error.message || 'Could not save the reply draft.'; render(); } }
async function connectInstagram() { try { const response = await call('start_meta_instagram_oauth'); window.location.assign(response.authorization_url); } catch (error) { state.error = error.message || 'Could not start the Instagram connection.'; render(); } }
function create(kind) { document.querySelector('.dialog')?.remove(); const actions = { launcher, carousel: () => creationForm('carousel'), reel: () => creationForm('reel'), 'image-to-reel': () => creationForm('image-to-reel'), image: () => creationForm('image'), pin: () => creationForm('pin'), x: () => creationForm('x'), article: articleModal, 'article-ideas': articleIdeas, asset: assetModal, brand: brandModal, connections: connectionModal, community: communityModal, opportunity: opportunityModal, calendar: () => scheduleModal(), variation: () => creationForm('image') }; actions[kind]?.(); }
function bind() {
  document.querySelectorAll('[data-login]').forEach(button => { button.onclick = () => signIn(button.dataset.login); }); document.querySelector('[data-preview]')?.addEventListener('click', startPreview, { once: true });
  document.querySelectorAll('[data-view]').forEach(button => { button.onclick = event => { if (button.tagName === 'A') event.preventDefault(); state.view = button.dataset.view; render(); }; }); document.querySelectorAll('[data-create]').forEach(button => { button.onclick = () => create(button.dataset.create); }); document.querySelectorAll('[data-close]').forEach(button => { button.onclick = () => document.querySelector('.dialog')?.remove(); }); document.querySelectorAll('[data-content]').forEach(button => { button.onclick = () => openContent(button.dataset.content); }); document.querySelectorAll('[data-asset]').forEach(button => { button.onclick = () => openAsset(button.dataset.asset); }); document.querySelectorAll('[data-edit-asset]').forEach(button => { button.onclick = () => assetEditModal(asset(button.dataset.editAsset)); }); document.querySelectorAll('[data-delete-asset]').forEach(button => { button.onclick = () => deleteAsset(button.dataset.deleteAsset); }); document.querySelectorAll('[data-delete-content]').forEach(button => { button.onclick = () => deleteContent(button.dataset.deleteContent); }); document.querySelectorAll('[data-refresh-video]').forEach(button => { button.onclick = () => refreshGeneratedVideo(button.dataset.refreshVideo); }); document.querySelectorAll('[data-opportunity]').forEach(button => { button.onclick = () => openOpportunity(button.dataset.opportunity); }); document.querySelectorAll('[data-calendar-step]').forEach(button => { button.onclick = () => { state.calendarOffset += Number(button.dataset.calendarStep); render(); }; });
  document.querySelectorAll('[data-idea]').forEach(button => { button.onclick = () => { document.querySelector('.dialog')?.remove(); articleModal(); document.querySelector('[name="title"]')?.setAttribute('value', button.dataset.idea); }; }); document.querySelectorAll('[data-creation]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveCreation(form); }; }); document.querySelectorAll('form[data-form="asset"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveAsset(form); }; }); document.querySelectorAll('form[data-form="asset-edit"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveAssetEdit(form); }; }); document.querySelectorAll('form[data-form="content"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveContentEdit(form); }; }); document.querySelectorAll('form[data-form="schedule"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveSchedule(form); }; }); document.querySelectorAll('form[data-form="brand"],form[data-form="community"],form[data-form="opportunity"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveGeneric(form); }; }); document.querySelectorAll('form[data-form="reply"]').forEach(form => { form.onsubmit = event => { event.preventDefault(); saveReply(form); }; }); document.querySelectorAll('[data-connect-instagram]').forEach(button => { button.onclick = connectInstagram; }); document.querySelectorAll('[data-connection-info]').forEach(button => { button.onclick = () => { state.error = 'This channel needs its own approved developer credentials before direct publishing or analytics can be enabled.'; render(); }; }); const signout = document.querySelector('[data-signout]'); if (signout) signout.onclick = () => { if (state.preview) { state.preview = false; state.session = null; state.error = ''; render(); } else supabase.auth.signOut(); };
}
function render() { if (!state.session) return login(); app.innerHTML = shell(); bind(); }
const { data: { session } } = await supabase.auth.getSession(); state.session = session; supabase.auth.onAuthStateChange((_event, nextSession) => { state.session = nextSession; if (nextSession) load(); else render(); }); if (session) load(); else render();
